WITH satscores_schools AS (SELECT sa.cds, s.soc, s.charter, sa.avgscrread, sa.avgscrmath, sa.avgscrwrite FROM satscores sa JOIN schools s ON sa.cds = s.cdscode WHERE sa.rtype = 'S')SELECT soc, charter, AVG(avgscrread) as avg_read, AVG(avgscrmath) as avg_math, AVG(avgscrwrite) as avg_write, COUNT(DISTINCT cds) as school_count FROM satscores_schools GROUP BY soc, charter ORDER BY soc, avg_read DESC;
